// src/components/AdminApp.tsx
import React from 'react';
import { Admin, Resource, defaultTheme } from 'react-admin';
import {dataProvider, sqlite3, createTemplateFromSchema} from "/myfinsheet-client/react-admin"

import DumbListGuesser from "./DumbListGuesser.jsx"
import DumbCreateGuesser from './DumbCreateGuesser.jsx';
import DumbEditGuesser from './DumbEditGuesser.jsx';

import { useEffect } from 'react';
import { useState } from 'react';
// const dataProvider = jsonServerProvider('https://jsonplaceholder.typicode.com');


const myTheme = {
    ...defaultTheme,
    components: {
        ...defaultTheme.components,
        MuiAppBar: {
            styleOverrides: {
                root: {
                    // This pushes the React Admin bar down
                    top: "4vh",
                },
            },
        }
    },
};

const AdminApp = () => {
  // 1. Properly initialize state and setter
  const [allSchema, setAllSchema] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadSchemas = async () => {
      try {
        const tables = await sqlite3.listTables();
        
        // 2. Create an array of promises to fetch all schemas in parallel
        const schemaPromises = tables.map(async (t) => {
          const schema = await sqlite3.getSchema(t.name);
          return {
            name: t.name,
            template: createTemplateFromSchema(schema)
          };
        });

        const results = await Promise.all(schemaPromises);

        // 3. Transform array to a single object
        const schemaMap = results.reduce((acc, curr) => {
          acc[curr.name] = curr.template;
          return acc;
        }, {});

        // 4. Update state (this triggers the re-render)
        setAllSchema(schemaMap);
        console.log(schemaMap);
        
      } finally {
        setLoading(false);
      }
    };

    loadSchemas();
  }, []);

  // 5. Wait for schemas to load before rendering Resources
  if (loading) return <div>Loading Database Schema...</div>;

  return (
    <div style={{height:"96vh", width:"100%", position: "sticky"}}>
    <Admin dataProvider={dataProvider} theme={myTheme}>
      {Object.keys(allSchema).map(k => <Resource 
        key={k}
        name={k}
        list={DumbListGuesser} 
        edit={DumbEditGuesser} 
        create={(props) => (
          <DumbCreateGuesser {...props} recordTemplate={allSchema[k]} />
        )}
      />)}
    </Admin>
    </div>
  );
};

export default AdminApp;