import React from 'react';
import { 
    Create, 
    SimpleForm, 
    TextInput, 
    NumberInput, 
    useListContext, 
    ListContextProvider 
} from 'react-admin';

import {DynamicFields} from "./DumbEditGuesser.jsx"

/**
 * A Form that generates inputs based on the keys of an object.
 */
const DynamicFormFields = ({ recordTemplate }) => {
    if (!recordTemplate) return null;

    return (
        <>
            {Object.keys(recordTemplate).map((key) => {
                // Skip the ID field as it's usually auto-generated by the DB
                if (key === 'id') return null;

                const value = recordTemplate[key];
                
                // Basic type detection
                if (typeof value === 'number') {
                    return <NumberInput key={key} source={key} />;
                }
                
                return <TextInput key={key} source={key} />;
            })}
        </>
    );
};

/** * DYNAMIC CREATE COMPONENT
 */
export const DumbCreateGuesser = ({ recordTemplate, ...props }) => (
    <Create 
        {...props} 
        transform={data => {
            const now = new Date().toISOString();
            return {
                ...data,
                create_ts: now, // Set creation time once
                modify_ts: now  // Set initial modification time
            };
        }}
    >
        <SimpleForm record={recordTemplate}>
            <DynamicFields recordTemplate={recordTemplate}/>
        </SimpleForm>
     </Create>
);

export default DumbCreateGuesser