import React from "react"
import { List, Datagrid, TextField, NumberField, SearchInput, useListContext } from 'react-admin';

const DumbDatagrid = () => {
    const { data } = useListContext();
    if (!data || data.length === 0) return null;

    // Grab keys from the first record to build columns dynamically
    const fields = Object.keys(data[0]);

    return (
        <Datagrid>
            {fields.map(field => {
                if (typeof data[0][field] === 'number') {
                    return <NumberField key={field} source={field} />;
                }
                return <TextField key={field} source={field} />;
            })}
        </Datagrid>
    );
};

const DumbListGuessor = (props) => (

    <List {...props} filters={[
    <SearchInput source="q" placeholder="search now ... " alwaysOn />]}>
        <DumbDatagrid />
    </List>
);

export default DumbListGuessor;