import { SQLiteClient, raw } from '@rushike/sqlite3-client/sqlite3.client.js';
import { DataProvider } from 'ra-core';
import sqlite3 from './sqlite3.js';

// Utility to wrap keys as raw SQL identifiers
const rawKeys = (obj: object) => Object.keys(obj).map(k => raw(k));
const rawVals = (obj: object) => Object.values(obj);

const dataProvider: DataProvider = {
    getList: async (resource, params) => {
        const table = raw(resource);
        const { page, perPage } = params.pagination;
        const offset = (page - 1) * perPage;


        const data = await sqlite3.supersql`
            SELECT * FROM ${table} 
            LIMIT ${perPage} OFFSET ${offset}
        `.all();

        const count = await sqlite3.supersql`
            SELECT COUNT(*) as total FROM ${table}
        `.get();

        return { data: data || [], total: count?.total ?? 0 };
    },

    getOne: async (resource, params) => {
        const table = raw(resource);
        const data = await sqlite3.supersql`
            SELECT * FROM ${table} WHERE id = ${params.id} LIMIT 1
        `.get();
        return { data };
    },

    getMany: async (resource, params) => {
        const table = raw(resource);
        const data = await sqlite3.supersql`
            SELECT * FROM ${table} WHERE id IN (${params.ids})
        `.all();
        return { data: data || [] };
    },

    getManyReference: async (resource, params) => {
        const table = raw(resource);
        const target = raw(params.target);
        const { page, perPage } = params.pagination;
        const offset = (page - 1) * perPage;

        const data = await sqlite3.supersql`
            SELECT * FROM ${table} WHERE ${target} = ${params.id} 
            LIMIT ${perPage} OFFSET ${offset}
        `.all();

        const count = await sqlite3.supersql`
            SELECT COUNT(*) as total FROM ${table} WHERE ${target} = ${params.id}
        `.get();

        return { data: data || [], total: count?.total ?? 0 };
    },

    create: async (resource, params) => {
        const table = raw(resource);
        let obj : Record<any, any> = {}
        Object.entries(params.data).map(([key, value] : [string, any]) => {
            if (key === "id") return
            obj[key] = value;
        })

        const columns = rawKeys(obj);
        const values = rawVals(obj);

        console.log("columns : values : ", columns, values, );
        
        await sqlite3.supersql`
            INSERT INTO ${table} (${columns}) VALUES (${values})
        `.run();

        const data = await sqlite3.supersql`
            SELECT * FROM ${table} WHERE id = last_insert_rowid()
        `.get();
        
        return { data };
    },

    update: async (resource, params) => {
        const table = raw(resource);
        const fields = Object.keys(params.data).filter(k => k !== 'id');
        
        // Build SET clause: col1 = ?, col2 = ?
        const setClauses = fields.map(f => sqlite3.supersql`${raw(f)} = ${params.data[f]}`);
        
        // Note: You can expand supersql logic to handle nested supersql templates 
        // Or simply join them here manually for the SET clause:
        const assignments = fields.map(f => `${f} = ?`).join(', ');
        const values = fields.map(f => params.data[f]);

        await sqlite3.supersql`
            UPDATE ${table} SET ${raw(assignments)} WHERE id = ${params.id}
        `.run(); // If using simple string join for assignments

        return { data: { ...params.previousData, ...params.data } };
    },

    updateMany: async (resource, params) => {
        const table = raw(resource);
        const fields = Object.keys(params.data).filter(k => k !== 'id');
        const assignments = fields.map(f => `${f} = ?`).join(', ');
        const values = fields.map(f => params.data[f]);

        await sqlite3.supersql`
            UPDATE ${table} SET ${raw(assignments)} WHERE id IN (${params.ids})
        `.run(); // params.ids is automatically expanded to ?,?,? by supersql
        
        return { data: params.ids };
    },

    delete: async (resource, params) => {
        const table = raw(resource);
        console.log("delte : ", resource, params);
        
        await sqlite3.supersql`DELETE FROM ${table} WHERE id = ${params.id}`.run();
        return { data: params.previousData };
    },

    deleteMany: async (resource, params) => {
        const table = raw(resource);
        await sqlite3.supersql`DELETE FROM ${table} WHERE id IN (${params.ids})`.run();
        return { data: params.ids };
    },
};

export default dataProvider;