import sqlite3 from '@rushike/sqlite3-client';
import dataProvider from './DataProvider';

// Define the shape of your SQLite schema object
interface ColumnDefinition {
    cid: number;
    name: string;
    type: string;
    notnull: number;
    dflt_value: any;
    pk: number;
}

// The resulting template will be a flexible object
type RecordTemplate = Record<string, string | number | boolean>;

/**
 * Transforms SQLite schema to a JS template object
 */
export const createTemplateFromSchema = (schema: ColumnDefinition[]): RecordTemplate => {
    const template: RecordTemplate = {};

    schema.forEach((col) => {
        // Skip Primary Keys (usually auto-incremented by DB)
        if (col.pk === 1) return;

        const type = col.type.toUpperCase();

        if (type.includes('INT') || type.includes('REAL') || type.includes('NUMERIC')) {
            template[col.name] = 0;
        } else if (type.includes('DATE') || type.includes('TIME')) {
            template[col.name] = new Date().toISOString();
        } else if (type.includes('BOOL')) {
            template[col.name] = false;
        } else {
            template[col.name] = '';
        }
    });

    return template;
};

export {
  sqlite3,
  dataProvider
}

