import React from 'react';
import { 
    Edit, 
    SimpleForm, 
    TextInput, 
    NumberInput,
    useEditContext 
} from 'react-admin';

export const DynamicFields = ({ recordTemplate = null }) => {
    // useRecordContext works in both Create and Edit views
    
    const record = recordTemplate ? recordTemplate : useEditContext().record;
    const create = recordTemplate ? true : false
    console.log("record in dynamic fields L ", record);
    
    if (!record) return null;

    return (
        <>
            {Object.keys(record).map((key) => {
                // console.log("pass record template : ", recordTemplate);
                
                // Handle primary key
                if (key === 'id') return <TextInput key={key} source={key} disabled />;

                // Logic for Timestamps: Always disabled to prevent manual updates
                if (key === 'create_ts' || key === 'modify_ts') {
                    return <TextInput key={key} source={key} disabled />;
                }

                const value = record[key];
                console.log("key : ", key);
                
                switch (typeof value) {
                    case "number" :
                        return <NumberInput key={key} source={key} value={value}/> 
                    default:
                        return <TextInput key={key} label = {<div>{key}</div>} source={key} fullWidth value={value}/>;

                }
            })}
        </>
    );
};

/** * DYNAMIC EDIT COMPONENT
 */
export const DumbEditGuesser = (props) => (
    <Edit 
        {...props} 
        mutationMode="pessimistic"
        transform={data => ({
            ...data,
            modify_ts: new Date().toISOString() // Update modification time on save
        })}
    >
        <SimpleForm >
            <DynamicFields />
        </SimpleForm>
    </Edit>
);

export default DumbEditGuesser;